# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/64e_hansard_annual_extend_2025.R
# 64e_hansard_annual_extend_2025.R
# Self-regarding speech ratio, 2020-2025 — extends speech_self_regarding_annual.csv
# forward using a live pull from the official Hansard API (hansard-api.parliament.uk),
# since both ParlSpeech V2 (stops Dec 2019) and the Evan Odell dataset (stops Jul 2020,
# archived, no further updates) leave this window uncovered.
#
# IDENTICAL dictionaries and scoring method to 64b_hansard_annual.R (archived) / 64d
# (the 1979-1988 extension).
#
# Source: sources_raw/hansard_api_pull_2020_2025/hansard_contributions_2020_2025_dedup.csv
# (see that folder's SOURCE_NOTE.md and pull_hansard_api.py for how it was built; 1,515
# exact-duplicate rows already removed, mostly from resuming the pull after a mid-run
# connection error).
#
# NOTE: 2025 here will be a PARTIAL year relative to whatever "now" is when this runs
# (pull covers through Dec 2025 by design, but check the actual max date present).
#
# OUTPUT: data/processed/speech_self_regarding_2020_2025.csv

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, stringr, purrr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
DATA_IN   <- file.path(WKBD_ROOT, "sources_raw/hansard_api_pull_2020_2025/hansard_contributions_2020_2025_dedup.csv")
DATA_OUT  <- file.path(PROJECT, "data/processed/speech_self_regarding_2020_2025.csv")

# ============================================================
# 1. LOAD
# ============================================================
cat("Loading Hansard API pull (2020-2025)...\n")
raw <- read_csv(DATA_IN, show_col_types = FALSE)
cat(sprintf("Loaded: %d rows\n", nrow(raw)))

# ============================================================
# 2. FILTER — 2020 onward (matches speech_self_regarding_annual.csv's boundary),
#    actual spoken content
# ============================================================
filtered <- raw |>
  mutate(
    date = as.Date(date),
    year = as.integer(format(date, "%Y")),
    text = text
  ) |>
  filter(
    year >= 2020, year <= 2025,
    !is.na(text), nchar(text) > 300
  )

cat(sprintf("After filter: %d speeches, %d years (%d to %d)\n",
            nrow(filtered), n_distinct(filtered$year),
            min(filtered$year), max(filtered$year)))
cat("Speeches per year:\n")
print(as.data.frame(count(filtered, year)), row.names = FALSE)
cat(sprintf("\nMax date present: %s (flags whether 2025 is a partial year in this run)\n",
            format(max(filtered$date))))

# ============================================================
# 3. SAMPLE — up to 1,500 per year, same seed, same method
# ============================================================
set.seed(42)
sample_df <- filtered |>
  group_by(year) |>
  group_modify(~ slice_sample(.x, n = min(1500, nrow(.x)))) |>
  ungroup()

cat(sprintf("\nSample: %d speeches across %d years\n",
            nrow(sample_df), n_distinct(sample_df$year)))

# ============================================================
# 4. DICTIONARIES — identical to 64b/64d
# ============================================================
career_terms <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister"
)

policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)

# ============================================================
# 5. SCORE — identical method
# ============================================================
score_speech <- function(text, terms) {
  text_lower <- tolower(text)
  sum(str_count(text_lower, fixed(terms)))
}

cat("\nScoring speeches...\n")
t0 <- Sys.time()

scored <- sample_df |>
  mutate(
    n_words    = str_count(text, "\\S+"),
    n_career   = map_int(text, score_speech, career_terms),
    n_policy   = map_int(text, score_speech, policy_terms),
    self_ratio = (n_career + 0.5) / (n_career + n_policy + 1)
  ) |>
  filter(n_words >= 50)

cat(sprintf("Scoring done in %.1f minutes\n", as.numeric(Sys.time() - t0, units = "mins")))
cat(sprintf("Scored: %d speeches\n", nrow(scored)))

# ============================================================
# 6. ANNUAL AGGREGATION — identical schema
# ============================================================
annual <- scored |>
  group_by(year) |>
  summarise(
    n_speeches      = n(),
    mean_self_ratio = mean(self_ratio),
    se_self_ratio   = sd(self_ratio) / sqrt(n()),
    .groups = "drop"
  ) |>
  arrange(year)

cat("\n=== ANNUAL SELF-REGARDING RATIO, 2020-2025 ===\n")
print(annual, n = 10)

write_csv(annual, DATA_OUT)
cat("\nSaved:", DATA_OUT, "\n")
